    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        check("isAnagram(\"listen\", \"silent\")", true, AnagramChecker.isAnagram("listen", "silent"));
        check("isAnagram(\"Dormitory\", \"Dirty Room\")", true, AnagramChecker.isAnagram("Dormitory", "Dirty Room"));
        check("isAnagram(\"hello\", \"world\")", false, AnagramChecker.isAnagram("hello", "world"));
        check("isAnagram(\"abc\", \"ab\")", false, AnagramChecker.isAnagram("abc", "ab"));
        check("isAnagram(\"conversation\", \"voices rant on\")", true, AnagramChecker.isAnagram("conversation", "voices rant on"));
        check("isAnagram(\"aab\", \"abb\")", false, AnagramChecker.isAnagram("aab", "abb"));
        check("isAnagram(\"\", \"\")", true, AnagramChecker.isAnagram("", ""));
